'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';

interface NavItem {
  label: string;
  href: string;
}

const navItems: NavItem[] = [
  { label: 'Home', href: '/' },
  { label: 'Saved Queries', href: '/saved-queries' },
];

export function SiteNav() {
  const pathname = usePathname();

  return (
    <nav role="navigation" className="bg-white border-b border-gray-200">
      <div className="max-w-7xl mx-auto px-6 py-0 flex items-center gap-8">
        {navItems.map((item) => {
          const isActive = pathname === item.href;
          return (
            <Link
              key={item.href}
              href={item.href}
              className={`py-3 px-0 border-b-2 transition-colors ${
                isActive
                  ? 'font-bold text-[#333333] border-gray-800'
                  : 'text-[#333333] border-transparent hover:border-gray-300'
              }`}
            >
              {item.label}
            </Link>
          );
        })}
      </div>
    </nav>
  );
}
